/**
 * WebPraat Web Worker.
 * Encapsulates the Praat C++ WASM runtime, offloading heavy DSP computation
 * and analysis from the UI thread, and exposing a typed API via Comlink.
 */

import * as Comlink from 'comlink';
import type { TextGridData } from '../types/praat';
import type {
  PraatWorkerApi,
  SoundInfo,
  PitchAnalysisParams,
  FormantAnalysisParams,
  SpectrogramAnalysisParams,
  IntensityAnalysisParams,
  SpectrogramData,
  PitchTrack,
  FormantTrack,
  IntensityTrack,
  SoundAnalysisResult,
} from '../types/wasm';
// @ts-expect-error - praatlib.js is generated by wasm build
import createPraatModule from '../../public/praatlib.js';

let Module: any = null;
let initialized = false;

// Wrapped bridge functions
let praat_bridge_init: () => number;
let praat_bridge_create_sound: (ptr: number, n: number, channels: number, fs: number, name: string) => number;
let praat_bridge_sound_read_from_memory: (ptr: number, length: number, name: string) => number;
let praat_bridge_destroy_object: (id: number) => void;
let praat_bridge_get_object_count: () => number;
let praat_bridge_get_object_name: (id: number) => string;
let praat_bridge_get_object_class: (id: number) => string;
let praat_bridge_sound_get_duration: (id: number) => number;
let praat_bridge_sound_get_sample_rate: (id: number) => number;
let praat_bridge_sound_get_num_samples: (id: number) => number;
let praat_bridge_sound_get_num_channels: (id: number) => number;
let praat_bridge_sound_get_channel_samples: (id: number, channel: number, dest: number, maxSamples: number) => number;
let praat_bridge_sound_save_as_wav_file: (id: number, path: string) => number;
let praat_bridge_sound_to_pitch: (id: number, time_step: number, floor: number, ceiling: number) => number;
let praat_bridge_sound_to_formant: (id: number, time_step: number, n_formants: number, max_freq: number, win_len: number) => number;
let praat_bridge_sound_to_spectrogram: (id: number, win_len: number, max_freq: number, time_step: number, shape: number) => number;
let praat_bridge_sound_to_intensity: (id: number, floor: number, time_step: number, subtract_mean: number) => number;
let praat_bridge_spectrogram_get_info: (id: number, out_info: number) => number;
let praat_bridge_spectrogram_get_matrix: (id: number, out_data: number) => number;
let praat_bridge_pitch_get_info: (id: number, out_info: number) => number;
let praat_bridge_pitch_get_frames: (id: number, out_frequencies: number) => number;
let praat_bridge_formant_get_info: (id: number, out_info: number) => number;
let praat_bridge_formant_get_frames: (id: number, out_frequencies: number) => number;
let praat_bridge_intensity_get_info: (id: number, out_info: number) => number;
let praat_bridge_intensity_get_frames: (id: number, out_values: number) => number;
let praat_bridge_pitch_get_mean: (id: number, tmin: number, tmax: number) => number;
let praat_bridge_pitch_get_value_at_time: (id: number, time: number) => number;
let praat_bridge_create_textgrid: (tmin: number, tmax: number, tier_names: string, point_tiers: string, name: string) => number;
let praat_bridge_sound_to_textgrid: (sound_id: number, tier_names: string, point_tiers: string) => number;
let praat_bridge_textgrid_to_json: (id: number) => string;
let praat_bridge_textgrid_save_to_file: (id: number, path: string) => number;
let praat_bridge_textgrid_read_from_file: (path: string, name: string) => number;
let praat_bridge_textgrid_insert_boundary: (id: number, tier_num: number, time: number) => number;
let praat_bridge_textgrid_remove_boundary_at_time: (id: number, tier_num: number, time: number) => number;
let praat_bridge_textgrid_set_interval_text: (id: number, tier_num: number, interval_num: number, text: string) => number;
let praat_bridge_textgrid_insert_point: (id: number, tier_num: number, time: number, mark: string) => number;
let praat_bridge_textgrid_set_point_text: (id: number, tier_num: number, point_num: number, text: string) => number;
let praat_bridge_execute_script: (text: string) => string;
let praat_bridge_get_info_output: () => string;

async function ensureInit(): Promise<boolean> {
  if (initialized && Module) return true;

  Module = await createPraatModule({
    locateFile(path: string, prefix: string) {
      if (path.endsWith('.wasm')) {
        if (typeof window !== 'undefined' || (typeof self !== 'undefined' && 'WorkerGlobalScope' in self)) {
          return '/praatlib.wasm';
        }
        return (prefix || '') + path;
      }
      return (prefix || '') + path;
    },
  });

  praat_bridge_init = Module.cwrap('praat_bridge_init', 'number', []);
  praat_bridge_create_sound = Module.cwrap('praat_bridge_create_sound', 'number', ['number', 'number', 'number', 'number', 'string']);
  praat_bridge_sound_read_from_memory = Module.cwrap('praat_bridge_sound_read_from_memory', 'number', ['number', 'number', 'string']);
  praat_bridge_destroy_object = Module.cwrap('praat_bridge_destroy_object', null, ['number']);
  praat_bridge_get_object_count = Module.cwrap('praat_bridge_get_object_count', 'number', []);
  praat_bridge_get_object_name = Module.cwrap('praat_bridge_get_object_name', 'string', ['number']);
  praat_bridge_get_object_class = Module.cwrap('praat_bridge_get_object_class', 'string', ['number']);
  praat_bridge_sound_get_duration = Module.cwrap('praat_bridge_sound_get_duration', 'number', ['number']);
  praat_bridge_sound_get_sample_rate = Module.cwrap('praat_bridge_sound_get_sample_rate', 'number', ['number']);
  praat_bridge_sound_get_num_samples = Module.cwrap('praat_bridge_sound_get_num_samples', 'number', ['number']);
  praat_bridge_sound_get_num_channels = Module.cwrap('praat_bridge_sound_get_num_channels', 'number', ['number']);
  praat_bridge_sound_get_channel_samples = Module.cwrap('praat_bridge_sound_get_channel_samples', 'number', ['number', 'number', 'number', 'number']);
  praat_bridge_sound_save_as_wav_file = Module.cwrap('praat_bridge_sound_save_as_wav_file', 'number', ['number', 'string']);
  praat_bridge_sound_to_pitch = Module.cwrap('praat_bridge_sound_to_pitch', 'number', ['number', 'number', 'number', 'number']);
  praat_bridge_sound_to_formant = Module.cwrap('praat_bridge_sound_to_formant', 'number', ['number', 'number', 'number', 'number', 'number']);
  praat_bridge_sound_to_spectrogram = Module.cwrap('praat_bridge_sound_to_spectrogram', 'number', ['number', 'number', 'number', 'number', 'number']);
  praat_bridge_sound_to_intensity = Module.cwrap('praat_bridge_sound_to_intensity', 'number', ['number', 'number', 'number', 'number']);
  praat_bridge_spectrogram_get_info = Module.cwrap('praat_bridge_spectrogram_get_info', 'number', ['number', 'number']);
  praat_bridge_spectrogram_get_matrix = Module.cwrap('praat_bridge_spectrogram_get_matrix', 'number', ['number', 'number']);
  praat_bridge_pitch_get_info = Module.cwrap('praat_bridge_pitch_get_info', 'number', ['number', 'number']);
  praat_bridge_pitch_get_frames = Module.cwrap('praat_bridge_pitch_get_frames', 'number', ['number', 'number']);
  praat_bridge_formant_get_info = Module.cwrap('praat_bridge_formant_get_info', 'number', ['number', 'number']);
  praat_bridge_formant_get_frames = Module.cwrap('praat_bridge_formant_get_frames', 'number', ['number', 'number']);
  praat_bridge_intensity_get_info = Module.cwrap('praat_bridge_intensity_get_info', 'number', ['number', 'number']);
  praat_bridge_intensity_get_frames = Module.cwrap('praat_bridge_intensity_get_frames', 'number', ['number', 'number']);
  praat_bridge_pitch_get_mean = Module.cwrap('praat_bridge_pitch_get_mean', 'number', ['number', 'number', 'number']);
  praat_bridge_pitch_get_value_at_time = Module.cwrap('praat_bridge_pitch_get_value_at_time', 'number', ['number', 'number']);
  praat_bridge_create_textgrid = Module.cwrap('praat_bridge_create_textgrid', 'number', ['number', 'number', 'string', 'string', 'string']);
  praat_bridge_sound_to_textgrid = Module.cwrap('praat_bridge_sound_to_textgrid', 'number', ['number', 'string', 'string']);
  praat_bridge_textgrid_to_json = Module.cwrap('praat_bridge_textgrid_to_json', 'string', ['number']);
  praat_bridge_textgrid_save_to_file = Module.cwrap('praat_bridge_textgrid_save_to_file', 'number', ['number', 'string']);
  praat_bridge_textgrid_read_from_file = Module.cwrap('praat_bridge_textgrid_read_from_file', 'number', ['string', 'string']);
  praat_bridge_textgrid_insert_boundary = Module.cwrap('praat_bridge_textgrid_insert_boundary', 'number', ['number', 'number', 'number']);
  praat_bridge_textgrid_remove_boundary_at_time = Module.cwrap('praat_bridge_textgrid_remove_boundary_at_time', 'number', ['number', 'number', 'number']);
  praat_bridge_textgrid_set_interval_text = Module.cwrap('praat_bridge_textgrid_set_interval_text', 'number', ['number', 'number', 'number', 'string']);
  praat_bridge_textgrid_insert_point = Module.cwrap('praat_bridge_textgrid_insert_point', 'number', ['number', 'number', 'number', 'string']);
  praat_bridge_textgrid_set_point_text = Module.cwrap('praat_bridge_textgrid_set_point_text', 'number', ['number', 'number', 'number', 'string']);
  praat_bridge_execute_script = Module.cwrap('praat_bridge_execute_script', 'string', ['string']);
  praat_bridge_get_info_output = Module.cwrap('praat_bridge_get_info_output', 'string', []);

  const res = praat_bridge_init();
  if (res !== 1) {
    throw new Error('praat_bridge_init failed in worker');
  }

  initialized = true;
  return true;
}

export const praatWorkerApi: PraatWorkerApi = {
  async init(): Promise<boolean> {
    return ensureInit();
  },

  async createSound(samples: Float64Array, n: number, channels: number, fs: number, name: string): Promise<number> {
    await ensureInit();
    const bytes = samples.length * 8;
    const ptr = Module._malloc(bytes);
    try {
      Module.HEAPF64.set(samples, ptr >> 3);
      const soundId = praat_bridge_create_sound(ptr, n, channels, fs, name);
      if (soundId <= 0) throw new Error(`Failed to create Sound object: ${name}`);
      return soundId;
    } finally {
      Module._free(ptr);
    }
  },

  async readSoundFromBuffer(buffer: Uint8Array, name: string): Promise<number> {
    await ensureInit();
    const ptr = Module._malloc(buffer.length);
    try {
      Module.HEAPU8.set(buffer, ptr);
      const soundId = praat_bridge_sound_read_from_memory(ptr, buffer.length, name);
      if (soundId <= 0) throw new Error(`Failed to decode audio file into Sound object: ${name}`);
      return soundId;
    } finally {
      Module._free(ptr);
    }
  },

  async destroyObject(id: number): Promise<void> {
    await ensureInit();
    praat_bridge_destroy_object(id);
  },

  async getObjectCount(): Promise<number> {
    await ensureInit();
    return praat_bridge_get_object_count();
  },

  async getObjectName(id: number): Promise<string> {
    await ensureInit();
    return praat_bridge_get_object_name(id);
  },

  async getObjectClass(id: number): Promise<string> {
    await ensureInit();
    return praat_bridge_get_object_class(id);
  },

  async getSoundInfo(soundId: number): Promise<SoundInfo> {
    await ensureInit();
    const duration = praat_bridge_sound_get_duration(soundId);
    const sampleRate = praat_bridge_sound_get_sample_rate(soundId);
    const numSamples = praat_bridge_sound_get_num_samples(soundId);
    const numChannels = praat_bridge_sound_get_num_channels(soundId);
    const name = praat_bridge_get_object_name(soundId);
    const className = praat_bridge_get_object_class(soundId);

    if (numSamples <= 0 || sampleRate <= 0.0) {
      throw new Error(`Invalid sound info retrieved for object ID ${soundId}`);
    }

    return {
      id: soundId,
      name,
      className,
      duration,
      sampleRate,
      numSamples,
      numChannels,
    };
  },

  async getSoundChannelSamples(soundId: number, channel: number): Promise<Float64Array> {
    await ensureInit();
    const numSamples = praat_bridge_sound_get_num_samples(soundId);
    if (numSamples <= 0) return new Float64Array(0);

    const bytes = numSamples * 8;
    const destPtr = Module._malloc(bytes);
    try {
      const read = praat_bridge_sound_get_channel_samples(soundId, channel, destPtr, numSamples);
      if (read <= 0) throw new Error(`Failed to read channel ${channel} samples for sound ${soundId}`);
      const result = new Float64Array(read);
      result.set(new Float64Array(Module.HEAPF64.buffer, destPtr, read));
      return result;
    } finally {
      Module._free(destPtr);
    }
  },

  async soundToPitch(soundId: number, params?: PitchAnalysisParams): Promise<number> {
    await ensureInit();
    const timeStep = params?.timeStep ?? 0.0;
    const floor = params?.pitchFloor ?? 75.0;
    const ceiling = params?.pitchCeiling ?? 600.0;
    const pitchId = praat_bridge_sound_to_pitch(soundId, timeStep, floor, ceiling);
    if (pitchId <= 0) throw new Error(`Failed to calculate Pitch from Sound ${soundId}`);
    return pitchId;
  },

  async soundToFormant(soundId: number, params?: FormantAnalysisParams): Promise<number> {
    await ensureInit();
    const timeStep = params?.timeStep ?? 0.0;
    const nFormants = params?.nFormants ?? 5;
    const maxFreq = params?.maxFormant ?? 5500.0;
    const winLen = params?.windowLength ?? 0.025;
    const formantId = praat_bridge_sound_to_formant(soundId, timeStep, nFormants, maxFreq, winLen);
    if (formantId <= 0) throw new Error(`Failed to calculate Formant from Sound ${soundId}`);
    return formantId;
  },

  async soundToSpectrogram(soundId: number, params?: SpectrogramAnalysisParams): Promise<number> {
    await ensureInit();
    const winLen = params?.windowLength ?? 0.005;
    const maxFreq = params?.maxFreq ?? 5000.0;
    const timeStep = params?.timeStep ?? 0.002;
    const shape = params?.windowShape ?? 0;
    const spectroId = praat_bridge_sound_to_spectrogram(soundId, winLen, maxFreq, timeStep, shape);
    if (spectroId <= 0) throw new Error(`Failed to calculate Spectrogram from Sound ${soundId}`);
    return spectroId;
  },

  async soundToIntensity(soundId: number, params?: IntensityAnalysisParams): Promise<number> {
    await ensureInit();
    const floor = params?.pitchFloor ?? 100.0;
    const timeStep = params?.timeStep ?? 0.0;
    const subtractMean = params?.subtractMean !== false ? 1 : 0;
    const intensityId = praat_bridge_sound_to_intensity(soundId, floor, timeStep, subtractMean);
    if (intensityId <= 0) throw new Error(`Failed to calculate Intensity from Sound ${soundId}`);
    return intensityId;
  },

  async getSpectrogramData(spectroId: number): Promise<SpectrogramData> {
    await ensureInit();
    const metaPtr = Module._malloc(10 * 8);
    try {
      const ok = praat_bridge_spectrogram_get_info(spectroId, metaPtr);
      if (!ok) throw new Error(`Failed to get Spectrogram info for ID ${spectroId}`);
      const meta = new Float64Array(Module.HEAPF64.buffer, metaPtr, 10);
      const [xmin, xmax, nx, dx, x1, ymin, ymax, ny, dy, y1] = Array.from(meta);
      const totalElements = Math.round(nx) * Math.round(ny);
      const dataPtr = Module._malloc(totalElements * 8);
      try {
        const dataOk = praat_bridge_spectrogram_get_matrix(spectroId, dataPtr);
        if (!dataOk) throw new Error(`Failed to get Spectrogram matrix for ID ${spectroId}`);
        const data = new Float64Array(totalElements);
        data.set(new Float64Array(Module.HEAPF64.buffer, dataPtr, totalElements));
        return {
          xmin,
          xmax,
          nx: Math.round(nx),
          dx,
          x1,
          ymin,
          ymax,
          ny: Math.round(ny),
          dy,
          y1,
          z: data,
        };
      } finally {
        Module._free(dataPtr);
      }
    } finally {
      Module._free(metaPtr);
    }
  },

  async getPitchTrack(pitchId: number): Promise<PitchTrack> {
    await ensureInit();
    const metaPtr = Module._malloc(6 * 8);
    try {
      const ok = praat_bridge_pitch_get_info(pitchId, metaPtr);
      if (!ok) throw new Error(`Failed to get Pitch info for ID ${pitchId}`);
      const meta = new Float64Array(Module.HEAPF64.buffer, metaPtr, 6);
      const [xmin, xmax, nx, dx, x1, ceiling] = Array.from(meta);
      const nFrames = Math.round(nx);
      const dataPtr = Module._malloc(nFrames * 8);
      try {
        const framesOk = praat_bridge_pitch_get_frames(pitchId, dataPtr);
        if (!framesOk) throw new Error(`Failed to get Pitch frames for ID ${pitchId}`);
        const frequencies = new Float64Array(nFrames);
        frequencies.set(new Float64Array(Module.HEAPF64.buffer, dataPtr, nFrames));
        return {
          xmin,
          xmax,
          nx: nFrames,
          dx,
          x1,
          ceiling,
          frequencies,
        };
      } finally {
        Module._free(dataPtr);
      }
    } finally {
      Module._free(metaPtr);
    }
  },

  async getFormantTrack(formantId: number): Promise<FormantTrack> {
    await ensureInit();
    const metaPtr = Module._malloc(6 * 8);
    try {
      const ok = praat_bridge_formant_get_info(formantId, metaPtr);
      if (!ok) throw new Error(`Failed to get Formant info for ID ${formantId}`);
      const meta = new Float64Array(Module.HEAPF64.buffer, metaPtr, 6);
      const [xmin, xmax, nx, dx, x1, maxnFormants] = Array.from(meta);
      const nFrames = Math.round(nx);
      const maxF = Math.round(maxnFormants);
      const total = nFrames * maxF;
      const dataPtr = Module._malloc(total * 8);
      try {
        const framesOk = praat_bridge_formant_get_frames(formantId, dataPtr);
        if (!framesOk) throw new Error(`Failed to get Formant frames for ID ${formantId}`);
        const frequencies = new Float64Array(total);
        frequencies.set(new Float64Array(Module.HEAPF64.buffer, dataPtr, total));
        return {
          xmin,
          xmax,
          nx: nFrames,
          dx,
          x1,
          maxnFormants: maxF,
          frequencies,
        };
      } finally {
        Module._free(dataPtr);
      }
    } finally {
      Module._free(metaPtr);
    }
  },

  async getIntensityTrack(intensityId: number): Promise<IntensityTrack> {
    await ensureInit();
    const metaPtr = Module._malloc(5 * 8);
    try {
      const ok = praat_bridge_intensity_get_info(intensityId, metaPtr);
      if (!ok) throw new Error(`Failed to get Intensity info for ID ${intensityId}`);
      const meta = new Float64Array(Module.HEAPF64.buffer, metaPtr, 5);
      const [xmin, xmax, nx, dx, x1] = Array.from(meta);
      const nFrames = Math.round(nx);
      const dataPtr = Module._malloc(nFrames * 8);
      try {
        const framesOk = praat_bridge_intensity_get_frames(intensityId, dataPtr);
        if (!framesOk) throw new Error(`Failed to get Intensity frames for ID ${intensityId}`);
        const values = new Float64Array(nFrames);
        values.set(new Float64Array(Module.HEAPF64.buffer, dataPtr, nFrames));
        return {
          xmin,
          xmax,
          nx: nFrames,
          dx,
          x1,
          values,
        };
      } finally {
        Module._free(dataPtr);
      }
    } finally {
      Module._free(metaPtr);
    }
  },

  async analyzeSoundForEditor(
    soundId: number,
    options?: {
      spectrogram?: boolean;
      pitch?: boolean;
      formant?: boolean;
      intensity?: boolean;
      spectrogramParams?: SpectrogramAnalysisParams;
      pitchParams?: PitchAnalysisParams;
      formantParams?: FormantAnalysisParams;
      intensityParams?: IntensityAnalysisParams;
    }
  ): Promise<SoundAnalysisResult> {
    await ensureInit();
    const res: SoundAnalysisResult = {};

    if (options?.spectrogram !== false) {
      try {
        const spectroId = await praatWorkerApi.soundToSpectrogram(soundId, options?.spectrogramParams);
        res.spectrogram = await praatWorkerApi.getSpectrogramData(spectroId);
      } catch (err) {
        console.warn('Spectrogram extraction failed:', err);
      }
    }

    if (options?.pitch !== false) {
      try {
        const pitchId = await praatWorkerApi.soundToPitch(soundId, options?.pitchParams);
        res.pitch = await praatWorkerApi.getPitchTrack(pitchId);
      } catch (err) {
        console.warn('Pitch extraction failed:', err);
      }
    }

    if (options?.formant !== false) {
      try {
        const formantId = await praatWorkerApi.soundToFormant(soundId, options?.formantParams);
        res.formants = await praatWorkerApi.getFormantTrack(formantId);
      } catch (err) {
        console.warn('Formant extraction failed:', err);
      }
    }

    if (options?.intensity !== false) {
      try {
        const intensityId = await praatWorkerApi.soundToIntensity(soundId, options?.intensityParams);
        res.intensity = await praatWorkerApi.getIntensityTrack(intensityId);
      } catch (err) {
        console.warn('Intensity extraction failed:', err);
      }
    }

    return res;
  },

  async pitchGetMean(pitchId: number, tmin?: number, tmax?: number): Promise<number> {
    await ensureInit();
    return praat_bridge_pitch_get_mean(pitchId, tmin ?? 0.0, tmax ?? 0.0);
  },

  async pitchGetValueAtTime(pitchId: number, time: number): Promise<number> {
    await ensureInit();
    return praat_bridge_pitch_get_value_at_time(pitchId, time);
  },

  async createTextGrid(tmin: number, tmax: number, tierNames?: string, pointTiers?: string, name?: string): Promise<number> {
    await ensureInit();
    const id = praat_bridge_create_textgrid(tmin, tmax, tierNames ?? '', pointTiers ?? '', name ?? 'grid');
    if (id <= 0) throw new Error('Failed to create TextGrid object');
    return id;
  },

  async soundToTextGrid(soundId: number, tierNames?: string, pointTiers?: string): Promise<number> {
    await ensureInit();
    const id = praat_bridge_sound_to_textgrid(soundId, tierNames ?? 'sentence', pointTiers ?? '');
    if (id <= 0) throw new Error(`Failed to create TextGrid from Sound ${soundId}`);
    return id;
  },

  async getTextGridData(textgridId: number): Promise<TextGridData> {
    await ensureInit();
    const jsonStr = praat_bridge_textgrid_to_json(textgridId);
    if (!jsonStr || jsonStr === '{}') throw new Error(`Failed to read TextGrid data for ID ${textgridId}`);
    return JSON.parse(jsonStr) as TextGridData;
  },

  async exportTextGridAsText(textgridId: number): Promise<string> {
    await ensureInit();
    const tempPath = `/tmp/export_tg_${textgridId}_${Date.now()}.TextGrid`;
    const ok = praat_bridge_textgrid_save_to_file(textgridId, tempPath);
    if (!ok) throw new Error(`Failed to export TextGrid ${textgridId} to file`);
    try {
      return Module.FS.readFile(tempPath, { encoding: 'utf8' });
    } finally {
      try { Module.FS.unlink(tempPath); } catch {}
    }
  },

  async readTextGridFromText(content: string, name?: string): Promise<number> {
    await ensureInit();
    const tempPath = `/tmp/import_tg_${Date.now()}.TextGrid`;
    Module.FS.writeFile(tempPath, content);
    try {
      const id = praat_bridge_textgrid_read_from_file(tempPath, name ?? 'imported_grid');
      if (id <= 0) throw new Error('Failed to parse and import TextGrid file');
      return id;
    } finally {
      try { Module.FS.unlink(tempPath); } catch {}
    }
  },

  async textgridInsertBoundary(textgridId: number, tierNumber: number, time: number): Promise<void> {
    await ensureInit();
    const ok = praat_bridge_textgrid_insert_boundary(textgridId, tierNumber, time);
    if (!ok) throw new Error(`Failed to insert boundary at ${time}s in tier ${tierNumber}`);
  },

  async textgridRemoveBoundary(textgridId: number, tierNumber: number, time: number): Promise<void> {
    await ensureInit();
    const ok = praat_bridge_textgrid_remove_boundary_at_time(textgridId, tierNumber, time);
    if (!ok) throw new Error(`Failed to remove boundary at ${time}s in tier ${tierNumber}`);
  },

  async textgridSetIntervalText(textgridId: number, tierNumber: number, intervalNumber: number, text: string): Promise<void> {
    await ensureInit();
    const ok = praat_bridge_textgrid_set_interval_text(textgridId, tierNumber, intervalNumber, text);
    if (!ok) throw new Error(`Failed to set interval text on tier ${tierNumber}, interval ${intervalNumber}`);
  },

  async textgridInsertPoint(textgridId: number, tierNumber: number, time: number, mark: string): Promise<void> {
    await ensureInit();
    const ok = praat_bridge_textgrid_insert_point(textgridId, tierNumber, time, mark);
    if (!ok) throw new Error(`Failed to insert point at ${time}s in tier ${tierNumber}`);
  },

  async textgridSetPointText(textgridId: number, tierNumber: number, pointNumber: number, text: string): Promise<void> {
    await ensureInit();
    const ok = praat_bridge_textgrid_set_point_text(textgridId, tierNumber, pointNumber, text);
    if (!ok) throw new Error(`Failed to set point text on tier ${tierNumber}, point ${pointNumber}`);
  },

  async exportSoundAsWav(soundId: number): Promise<Uint8Array> {
    await ensureInit();
    const tempPath = `/tmp/export_${soundId}_${Date.now()}.wav`;
    const ok = praat_bridge_sound_save_as_wav_file(soundId, tempPath);
    if (!ok) throw new Error(`Failed to export sound ${soundId} as WAV`);

    try {
      const wavBytes = Module.FS.readFile(tempPath);
      return new Uint8Array(wavBytes.buffer, wavBytes.byteOffset, wavBytes.byteLength);
    } finally {
      try { Module.FS.unlink(tempPath); } catch {}
    }
  },

  async executeScript(scriptText: string): Promise<string> {
    await ensureInit();
    return praat_bridge_execute_script(scriptText);
  },

  async getInfoOutput(): Promise<string> {
    await ensureInit();
    return praat_bridge_get_info_output();
  },
};

// Expose via Comlink in Worker scope
if (typeof self !== 'undefined' && typeof (self as any).postMessage === 'function') {
  Comlink.expose(praatWorkerApi);
}

export default praatWorkerApi;
